import{GYM5_GAMEPLAY,GYM5_REVISION,GYM5_GAMEPLAY_REVISION}from'./fixed-registration.mjs';import{gym5VisualState}from'./gym5-visual-state.mjs';
const authorities=new WeakMap(),grants=new WeakMap();
const record=(o,keys)=>{if(!o||Object.getPrototypeOf(o)!==Object.prototype||Reflect.ownKeys(o).length!==keys.length)return null;const r={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(o,k);if(!d?.enumerable||!Object.hasOwn(d,'value'))return null;r[k]=d.value}return r};
const row=id=>GYM5_GAMEPLAY.find(r=>r.pointId===id);
export function isGym5Request(id,a){const r=row(id),d=record(a,['type']);return !!r&&d?.type===r.kind}
export function createGym5Authority({getWorld,readNative,getSignal}={}){if(typeof getWorld!=='function'||typeof readNative!=='function'||typeof getSignal!=='function')throw Error('LIVE_GYM5_OWNER_REQUIRED');const a=Object.freeze({});authorities.set(a,{getWorld,readNative,getSignal});return a}
export const isGym5Authority=a=>authorities.has(a);
export function gym5Facing(r,foot){if(r.kind==='puzzle')return'up';const dx=r.anchor[0]-foot[0],dy=r.anchor[1]-foot[1];return Math.abs(dy)>=Math.abs(dx)?dy>=0?'down':'up':dx>=0?'right':'left'}
function read(o,r,w){const n=record(o.readNative(),['version','sceneId','mapId','revision','imageSHA','maskSHA','foot','facing','phase','sessionEpoch','gameplayRevision','state']);if(!n||n.version!==1||n.phase!=='field'||n.sceneId!=='native:gym:5'||n.mapId!=='world:gym:5'||n.revision!==GYM5_REVISION||n.gameplayRevision!==GYM5_GAMEPLAY_REVISION||!Number.isSafeInteger(n.sessionEpoch)||n.sessionEpoch<1||!Number.isInteger(n.state)||n.state<0||n.state>3||n.state!==gym5VisualState(w.snapshot(),w.story.contract))return null;const pin=r.states[n.state];if(n.imageSHA!==pin.imageSHA||n.maskSHA!==pin.maskSHA)return null;const f=n.foot;if(!Array.isArray(f)||Object.getPrototypeOf(f)!==Array.prototype||Reflect.ownKeys(f).length!==3||Object.getOwnPropertyDescriptor(f,'length')?.value!==2)return null;const dx=Object.getOwnPropertyDescriptor(f,'0'),dy=Object.getOwnPropertyDescriptor(f,'1');if(!dx?.enumerable||!dy?.enumerable||!Object.hasOwn(dx,'value')||!Object.hasOwn(dy,'value'))return null;const x=dx.value,y=dy.value;if(!Number.isSafeInteger(x)||!Number.isSafeInteger(y)||!pin.rows.some(([yy,a,b])=>yy===y&&x>=a&&x<b)||n.facing!==gym5Facing(r,[x,y]))return null;return{epoch:n.sessionEpoch,x,y,facing:n.facing,state:n.state}}
function canonical(w,r){const s=w.snapshot(),p=w.definition.points[r.pointId];if(s.position.scene!=='world:gym:5'||s.world.mapId!=='world:gym:5'||JSON.stringify(p)!==JSON.stringify(r.sourceRow))return false;if(r.kind==='trainer')return w.story.trainerAvailable(p.trainerId)||(!w.story.contract.trainers[p.trainerId]?.repeatable&&s.progress.defeatedTrainers.includes(p.trainerId));return true}
export function mintGym5Grant(a,w,id){const o=authorities.get(a),r=row(id);if(!o||o.getWorld()!==w||!r||!canonical(w,r))throw Error('GYM5_UNAVAILABLE');const n=read(o,r,w),signal=o.getSignal();if(!n)throw Error('GYM5_APPROACH_REQUIRED');if(!(signal instanceof AbortSignal)||signal.aborted)throw Error('GYM5_LIFECYCLE_REQUIRED');const g=Object.freeze({});grants.set(g,{a,w,r,n,signal});return g}
export function validateGym5Grant(g,w,pointId){const q=grants.get(g),o=q&&authorities.get(q.a);if(!q||q.w!==w||!o||o.getWorld()!==w||q.signal.aborted||o.getSignal()!==q.signal||pointId!==undefined&&q.r.pointId!==pointId||!canonical(w,q.r))return false;const n=read(o,q.r,w);return !!n&&JSON.stringify(n)===JSON.stringify(q.n)}
export function assertGym5Grant(g,w){if(!validateGym5Grant(g,w))throw Error('GYM5_OWNER_DRIFT')}
export function revokeGym5Grant(g){grants.delete(g)}
export function signalGym5Grant(g,w){assertGym5Grant(g,w);return grants.get(g).signal}
